package provider

import (
	"fmt"
	"strings"

	"github.com/antlr4-go/antlr/v4"

	"github.com/beyondeye/aitasks/goengines/t1954research/provider/antlrgen/java"
	"github.com/beyondeye/aitasks/goengines/t1954research/provider/antlrgen/kotlin"
	"github.com/beyondeye/aitasks/goengines/t1954research/provider/antlrgen/rust"
)

func init() { register("antlr", func() (Provider, error) { return ANTLR{}, nil }) }

// ANTLR is the ANTLR4 Go runtime (github.com/antlr4-go/antlr/v4 v4.13.1)
// running grammars-v4 LEXERS generated by antlr/gen.sh (pins in antlr/LOCK)
// for Kotlin, Java and Rust. TypeScript is absent: grammars-v4 has no Go
// target base class for it.
//
// Comments are hidden-channel tokens; every channel is walked. The runtime
// indexes RUNES, so offsets go through RuneOffsets (t1954_3 contract) and
// every token's text is checked against the original bytes (Layer 1).
// Recognition errors become Diags at the failing token's start: the runtime's
// safeMatch reports, calls Recover and returns LexerSkip, so the offending
// character yields no token and the gap it leaves is explained by that Diag.
// The runtime keeps its mode stack unexported, so an unclosed string mode at
// EOF is not observable and no diagnostic is invented for it.
type ANTLR struct{}

type antlrGrammar struct {
	newLexer  func(antlr.CharStream) (antlr.Lexer, func() int)
	comment   map[int]TokClass // token type -> line/block comment (0: classify by text)
	literal   map[int]bool     // single-token literals
	open      map[int]bool     // multi-token literal openers (Kotlin string templates)
	close     map[int]bool
	skipRules bool // the grammar has `-> skip` rules (gaps without a Diag are documented omissions)
}

var antlrGrammars = map[string]antlrGrammar{
	"kotlin": {
		newLexer: func(in antlr.CharStream) (antlr.Lexer, func() int) {
			l := antlrkotlin.NewKotlinLexer(in)
			return l, func() int { return l.TokenStartCharIndex }
		},
		comment: map[int]TokClass{
			antlrkotlin.KotlinLexerShebangLine: TLineComment, antlrkotlin.KotlinLexerLineComment: TLineComment,
			antlrkotlin.KotlinLexerDelimitedComment: TBlockComment,
			antlrkotlin.KotlinLexerInside_Comment:   0, antlrkotlin.KotlinLexerStrExpr_Comment: 0,
		},
		literal: map[int]bool{antlrkotlin.KotlinLexerCharacterLiteral: true},
		open:    map[int]bool{antlrkotlin.KotlinLexerQUOTE_OPEN: true, antlrkotlin.KotlinLexerTRIPLE_QUOTE_OPEN: true},
		close:   map[int]bool{antlrkotlin.KotlinLexerQUOTE_CLOSE: true, antlrkotlin.KotlinLexerTRIPLE_QUOTE_CLOSE: true},
		// WS, Inside_WS, Inside_NL, MultiLineNL, StrExpr_WS, StrExpr_NL -> skip
		skipRules: true,
	},
	"java": {
		newLexer: func(in antlr.CharStream) (antlr.Lexer, func() int) {
			l := antlrjava.NewJavaLexer(in)
			return l, func() int { return l.TokenStartCharIndex }
		},
		comment: map[int]TokClass{antlrjava.JavaLexerLINE_COMMENT: TLineComment, antlrjava.JavaLexerCOMMENT: TBlockComment},
		literal: map[int]bool{antlrjava.JavaLexerSTRING_LITERAL: true, antlrjava.JavaLexerTEXT_BLOCK: true, antlrjava.JavaLexerCHAR_LITERAL: true},
	},
	"rust": {
		newLexer: func(in antlr.CharStream) (antlr.Lexer, func() int) {
			l := antlrrust.NewRustLexer(in)
			return l, func() int { return l.TokenStartCharIndex }
		},
		comment: map[int]TokClass{
			antlrrust.RustLexerLINE_COMMENT: TLineComment, antlrrust.RustLexerINNER_LINE_DOC: TLineComment,
			antlrrust.RustLexerOUTER_LINE_DOC: TLineComment, antlrrust.RustLexerSHEBANG: TLineComment,
			antlrrust.RustLexerBLOCK_COMMENT: TBlockComment, antlrrust.RustLexerINNER_BLOCK_DOC: TBlockComment,
			antlrrust.RustLexerOUTER_BLOCK_DOC: TBlockComment, antlrrust.RustLexerBLOCK_COMMENT_OR_DOC: TBlockComment,
		},
		literal: map[int]bool{
			antlrrust.RustLexerCHAR_LITERAL: true, antlrrust.RustLexerSTRING_LITERAL: true, antlrrust.RustLexerRAW_STRING_LITERAL: true,
			antlrrust.RustLexerBYTE_LITERAL: true, antlrrust.RustLexerBYTE_STRING_LITERAL: true, antlrrust.RustLexerRAW_BYTE_STRING_LITERAL: true,
		},
	},
}

func (ANTLR) Name() string    { return "antlr" }
func (ANTLR) Langs() []string { return []string{"kotlin", "java", "rust"} }

// Caps: token recognition errors are reported (Errors). FullCover only for
// grammars without skip rules (Java, Rust); the partition is then required
// only on inputs with no Diag (Layer 1). A lexer determines no anchors.
func (ANTLR) Caps(lang string) Capabilities {
	return Capabilities{TokenRanges: true, Errors: true, FullCover: !antlrGrammars[lang].skipRules}
}

// diagListener turns lexer recognition errors into rune-indexed diagnostics.
type diagListener struct {
	*antlr.DefaultErrorListener
	start func() int
	errs  []struct {
		at  int
		msg string
	}
}

func (d *diagListener) SyntaxError(_ antlr.Recognizer, _ any, _, _ int, msg string, _ antlr.RecognitionException) {
	d.errs = append(d.errs, struct {
		at  int
		msg string
	}{d.start(), msg})
}

// Analyze lexes src with the language's generated lexer.
func (ANTLR) Analyze(lang string, src []byte) (Result, error) {
	g, ok := antlrGrammars[lang]
	if !ok {
		return Result{}, fmt.Errorf("antlr: no grammar for %s", lang)
	}
	body, base, err := StrictUTF8(src)
	if err != nil {
		return Result{}, err
	}
	ro := NewRuneOffsets(body, base)
	lx, start := g.newLexer(antlr.NewInputStream(string(body)))
	dl := &diagListener{DefaultErrorListener: antlr.NewDefaultErrorListener(), start: start}
	lx.RemoveErrorListeners()
	lx.AddErrorListener(dl)
	var toks []RawToken
	var types []int
	for {
		t := lx.NextToken()
		if t.GetTokenType() == antlr.TokenEOF {
			break
		}
		s, e1 := t.GetStart(), t.GetStop()+1 // Stop is inclusive
		bs, err1 := ro.Byte(s)
		be, err2 := ro.Byte(e1)
		if err1 != nil || err2 != nil {
			return Result{}, adapterErr("token [%d,%d] runes: %v %v", s, t.GetStop(), err1, err2)
		}
		toks = append(toks, RawToken{Start: bs, End: be, Text: []byte(t.GetText()), Type: fmt.Sprint(t.GetTokenType())})
		types = append(types, t.GetTokenType())
	}
	var res Result
	for _, e := range dl.errs {
		b, err := ro.Byte(e.at)
		if err != nil {
			return Result{}, adapterErr("diagnostic rune index %d: %v", e.at, err)
		}
		res.Diags = append(res.Diags, Diag{b, b, "antlr: " + e.msg})
	}
	if _, err := ValidateTokens(src, toks, res.Diags, GapPolicy{SkipRules: g.skipRules}); err != nil {
		return Result{}, err
	}
	for i, t := range toks {
		if c, ok := g.comment[types[i]]; ok {
			if c == 0 {
				c = commentClass(string(t.Text))
			}
			kind := LineComment
			if c == TBlockComment {
				kind = BlockComment
			}
			end := t.End
			for kind == LineComment && end > t.Start && (src[end-1] == '\n' || src[end-1] == '\r') {
				end--
			}
			res.Spans = append(res.Spans, Span{t.Start, end, kind})
		}
		if g.literal[types[i]] {
			res.Spans = append(res.Spans, Span{t.Start, t.End, String})
		}
	}
	if len(g.open) > 0 {
		res.Spans = append(res.Spans, Bracketed(len(toks),
			func(i int) (int, int) { return toks[i].Start, toks[i].End },
			func(i int) bool { return g.open[types[i]] }, func(i int) bool { return g.close[types[i]] })...)
	}
	SortSpans(res.Spans)
	if !g.skipRules && len(res.Diags) == 0 {
		res.Leaves = LeavesOf(toks)
		if strings.HasPrefix(string(src), string(BOM)) {
			res.Leaves = append([]Span{{0, len(BOM), Other}}, res.Leaves...)
		}
	}
	return res, nil
}
